class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def insert_at_end(head, data):
    new_node = Node(data)
    if head is None:
        return new_node
    current = head
    while current.next:
        current = current.next
    current.next = new_node
    return head

def print_list(head):
    result = []
    current = head
    while current:
        result.append(str(current.data))
        current = current.next
    print(' '.join(result))

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    if n == 0:
        print()
        return
    nums = list(map(int, data[1:n+1]))
    head = None
    for num in nums:
        head = insert_at_end(head, num)
    print_list(head)

if __name__ == "__main__":
    main()
